                    {
                        Model = (ParlayWonModel)getDataFromCache;
                    }
                    else
                    {
                        Model = GetParlayBusiness(winlostDate, betType, isSoccer, moveBetsDay, balanceUpDay, false, string.Empty, pageIndex, pageSize, sortBy);
